CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','mentor','college','organizer','admin') NOT NULL DEFAULT 'student',verified BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS students(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,college VARCHAR(160),branch VARCHAR(100),study_year TINYINT,location VARCHAR(120),preferred_role VARCHAR(100),interests JSON,github VARCHAR(255),linkedin VARCHAR(255),portfolio VARCHAR(255),availability VARCHAR(80),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(college),INDEX(branch));
CREATE TABLE IF NOT EXISTS skills(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL UNIQUE,category VARCHAR(80));
CREATE TABLE IF NOT EXISTS student_skills(student_id BIGINT,skill_id BIGINT,proficiency TINYINT DEFAULT 3,CHECK(proficiency BETWEEN 1 AND 5),PRIMARY KEY(student_id,skill_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id));
CREATE TABLE IF NOT EXISTS projects(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_id BIGINT NOT NULL,title VARCHAR(160),description TEXT,domain VARCHAR(100),technologies JSON,link VARCHAR(255),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS hackathons(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(180) NOT NULL,organizer VARCHAR(180),description TEXT,domain VARCHAR(100),mode ENUM('Online','Offline','Hybrid'),venue VARCHAR(180),prize VARCHAR(120),min_team_size TINYINT DEFAULT 2,max_team_size TINYINT DEFAULT 6,allowed_branches JSON,allowed_years JSON,required_skills JSON,deadline DATE,event_date DATE,registration_link VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(deadline),INDEX(domain));
CREATE TABLE IF NOT EXISTS teams(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(140) NOT NULL,leader_id BIGINT NOT NULL,hackathon_id BIGINT,description TEXT,domain VARCHAR(100),max_size TINYINT DEFAULT 6,required_roles JSON,required_skills JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(leader_id) REFERENCES users(id),FOREIGN KEY(hackathon_id) REFERENCES hackathons(id) ON DELETE SET NULL,INDEX(domain));
CREATE TABLE IF NOT EXISTS team_members(team_id BIGINT,user_id BIGINT,team_role VARCHAR(100),status ENUM('active','left') DEFAULT 'active',PRIMARY KEY(team_id,user_id),FOREIGN KEY(team_id) REFERENCES teams(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS team_applications(id BIGINT PRIMARY KEY AUTO_INCREMENT,team_id BIGINT NOT NULL,student_user_id BIGINT NOT NULL,message TEXT,status ENUM('pending','accepted','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(team_id,student_user_id),FOREIGN KEY(team_id) REFERENCES teams(id) ON DELETE CASCADE,FOREIGN KEY(student_user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS mentors(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,title VARCHAR(140),organization VARCHAR(160),years_experience TINYINT DEFAULT 0,skills JSON,domains JSON,previous_teams INT DEFAULT 0,wins INT DEFAULT 0,available BOOLEAN DEFAULT TRUE,bio TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS mentorship_requests(id BIGINT PRIMARY KEY AUTO_INCREMENT,mentor_id BIGINT NOT NULL,team_id BIGINT NOT NULL,requested_by BIGINT NOT NULL,message TEXT,status ENUM('pending','accepted','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(mentor_id,team_id),FOREIGN KEY(mentor_id) REFERENCES mentors(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(requested_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS announcements(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(created_at));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,type VARCHAR(60),title VARCHAR(180),body TEXT,read_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id,read_at));
CREATE TABLE IF NOT EXISTS hackathon_applications(id BIGINT PRIMARY KEY AUTO_INCREMENT,hackathon_id BIGINT NOT NULL,team_id BIGINT NOT NULL,status ENUM('draft','submitted','accepted','rejected') DEFAULT 'draft',applied_at TIMESTAMP NULL,UNIQUE(hackathon_id,team_id),FOREIGN KEY(hackathon_id) REFERENCES hackathons(id),FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE IF NOT EXISTS match_scores(id BIGINT PRIMARY KEY AUTO_INCREMENT,team_id BIGINT NOT NULL,target_type ENUM('hackathon','mentor'),target_id BIGINT NOT NULL,score DECIMAL(5,2),explanation JSON,calculated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(team_id,target_type));
CREATE TABLE IF NOT EXISTS team_pool(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_user_id BIGINT NOT NULL UNIQUE,hackathon_id BIGINT NULL,preferred_domain VARCHAR(100),status ENUM('waiting','matched','cancelled') DEFAULT 'waiting',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(hackathon_id) REFERENCES hackathons(id) ON DELETE SET NULL);
